<?php require_once __DIR__.'/config/config.php'; $where=['active=1'];$args=[];if(!empty($_GET['category'])){$where[]='category=?';$args[]=$_GET['category'];}if(!empty($_GET['q'])){$where[]='(name LIKE ? OR description LIKE ?)';$args[]='%'.$_GET['q'].'%';$args[]='%'.$_GET['q'].'%';}$sort=($_GET['sort']??'latest')==='price'?'COALESCE(NULLIF(sale_price,0),price) ASC':'created_at DESC';$st=$pdo->prepare('SELECT * FROM products WHERE '.implode(' AND ',$where).' ORDER BY '.$sort);$st->execute($args);$products=$st->fetchAll();$pageTitle='Shop Watches | WatchesError';require 'includes/header.php';?>
